package local.tv.launcher;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class CatalogClientTest {
 @Test public void sparseSearchKeepsIdentityWithoutInventingFields()throws Exception{JSONObject item=CatalogClient.normalize(new JSONObject("{\"id\":\"tt1160419\",\"type\":\"movie\",\"name\":\"Dune\",\"releaseInfo\":\"2021\"}"),"movie");assertEquals("movie:tt1160419",item.getString("key"));assertEquals("tt1160419",item.getString("imdbId"));assertEquals("2021",item.getString("year"));assertEquals("",item.getString("overview"));assertEquals("",item.getString("poster"));assertFalse(item.has("rating"));assertFalse(item.has("runtime"));assertEquals(0,item.getJSONArray("cast").length());}
 @Test public void mapsRichMetadataAndEpisodeIdentity()throws Exception{JSONObject raw=new JSONObject("{\"id\":\"tt0944947\",\"type\":\"series\",\"name\":\"Game of Thrones\",\"description\":\"Story\",\"releaseInfo\":\"2011–2019\",\"runtime\":\"57 min\",\"imdbRating\":\"9.2\",\"genres\":[\"Drama\"],\"cast\":[\"Emilia Clarke\"],\"director\":[\"Director\"],\"writer\":[\"Writer\"],\"videos\":[{\"id\":\"tt0944947:1:2\",\"season\":1,\"number\":2,\"name\":\"Episode\"},{\"id\":\"tt0000001:1:3\",\"season\":1,\"episode\":3}]}");JSONObject item=CatalogClient.normalize(raw,"series");assertEquals(57,item.getInt("runtime"));assertEquals(9.2,item.getDouble("rating"),.001);assertEquals("Emilia Clarke",item.getJSONArray("cast").getJSONObject(0).getString("name"));assertEquals("Director",item.getJSONArray("directors").getString(0));assertEquals(1,item.getJSONArray("episodes").length());assertEquals(1,item.getJSONArray("seasons").getInt(0));assertEquals(2,item.getJSONArray("episodes").getJSONObject(0).getInt("episode"));}
 @Test public void malformedOrCrossTypeMetadataIsRejected()throws Exception{assertNull(CatalogClient.normalize(new JSONObject("{\"id\":438631,\"type\":\"movie\",\"name\":\"Dune\"}"),"movie"));assertNull(CatalogClient.normalize(new JSONObject("{\"id\":\"tt1160419\",\"type\":\"series\",\"name\":\"Dune\"}"),"movie"));assertNull(CatalogClient.normalize(new JSONObject("{\"id\":\"tt1160419\"}"),"movie"));assertNull(CatalogClient.normalize(null,"movie"));}
 @Test public void catalogsDeduplicateAndOmitHeavyEpisodeLists()throws Exception{JSONObject raw=new JSONObject("{\"id\":\"tt0944947\",\"type\":\"series\",\"name\":\"Game of Thrones\",\"videos\":[{\"id\":\"tt0944947:1:1\",\"season\":1,\"episode\":1}]}");JSONArray items=CatalogClient.normalizeList(new JSONArray().put(raw).put(raw),"series");assertEquals(1,items.length());assertEquals(0,items.getJSONObject(0).getJSONArray("episodes").length());}
}
